export function playBlob(blob: Blob, signal: AbortSignal): Promise<void> {
  return new Promise((resolve, reject) => {
    if (signal.aborted) return reject(new DOMException("Stopped", "AbortError"));
    const url = URL.createObjectURL(blob);
    const audio = new Audio(url);
    const finish = (err?: unknown) => {
      audio.pause();
      audio.removeAttribute("src");
      URL.revokeObjectURL(url);
      signal.removeEventListener("abort", abort);
      if (err) reject(err); else resolve();
    };
    const abort = () => finish(new DOMException("Stopped", "AbortError"));
    signal.addEventListener("abort", abort, { once: true });
    audio.onended = () => finish();
    audio.onerror = () => finish(new Error("Audio couldn't play. Tap Continue to try again."));
    audio.play().catch(finish);
  });
}

export class Microphone {
  private stream?: MediaStream;
  private socket?: WebSocket;
  private recorder?: MediaRecorder;
  private keepalive?: ReturnType<typeof setInterval>;
  private stopped = false;

  async start(onInterim: (text: string) => void, onFinal: (text: string) => void, onError: (message: string) => void) {
    if (!navigator.mediaDevices?.getUserMedia) throw new Error("Microphone needs HTTPS or localhost and a supported browser.");
    this.stream = await navigator.mediaDevices.getUserMedia({ audio: { echoCancellation: true, noiseSuppression: true, autoGainControl: true } });
    if (this.stopped) { this.stop(); return; }
    try {
      const { token } = await post<{ token: string }>("/api/deepgram-token", {});
      if (this.stopped) { this.stop(); return; }
      const params = new URLSearchParams({ model: "nova-3", language: "en-US", interim_results: "true", smart_format: "true", endpointing: "350", utterance_end_ms: "1000", vad_events: "true" });
      const socket = this.socket = new WebSocket(`wss://api.deepgram.com/v1/listen?${params}`, ["bearer", token]);
      await new Promise<void>((resolve, reject) => {
        const timeout = setTimeout(() => reject(new Error("Microphone connection timed out.")), 10000);
        socket.onopen = () => { clearTimeout(timeout); resolve(); };
        socket.onerror = () => { clearTimeout(timeout); reject(new Error("Couldn't connect to Deepgram.")); };
        socket.onclose = () => { clearTimeout(timeout); reject(new Error("Microphone connection closed.")); };
      });
      if (this.stopped) { this.stop(); return; }
      let pending = "";
      const flush = () => { if (pending.trim()) onFinal(pending.trim()); pending = ""; };
      socket.onmessage = (event) => {
        const msg = JSON.parse(event.data);
        const text = msg.channel?.alternatives?.[0]?.transcript;
        if (text) {
          onInterim(text);
          if (msg.is_final) pending += ` ${text}`;
        }
        if (msg.speech_final || msg.type === "UtteranceEnd") flush();
      };
      socket.onclose = () => { if (!this.stopped) { this.stop(); onError("The microphone disconnected. Turn Play mode on again to reconnect."); } };
      socket.onerror = () => onError("Microphone connection error.");
      const mimeType = ["audio/webm;codecs=opus", "audio/ogg;codecs=opus", "audio/mp4"].find(t => MediaRecorder.isTypeSupported(t));
      this.recorder = new MediaRecorder(this.stream, mimeType ? { mimeType } : undefined);
      this.recorder.ondataavailable = e => { if (e.data.size && socket.readyState === WebSocket.OPEN) socket.send(e.data); };
      this.recorder.start(100);
      this.keepalive = setInterval(() => { if (socket.readyState === WebSocket.OPEN) socket.send(JSON.stringify({ type: "KeepAlive" })); }, 5000);
    } catch (err) { this.stop(); throw err; }
  }

  stop() {
    this.stopped = true;
    clearInterval(this.keepalive);
    if (this.recorder?.state === "recording") this.recorder.stop();
    this.stream?.getTracks().forEach(t => t.stop());
    this.socket?.close();
  }
}
"}
{"file":"app/api/image/route.ts","body":"import { z } from "zod";
import { buildImagePrompt } from "@/lib/engine/imagePrompt";
import { falImage } from "@/lib/server/fal";
import { errorResponse } from "@/lib/server/errors";

const Body = z.object({
  scene: z.string().trim().min(1).max(800),
  artStyle: z.string().max(500),
  characters: z.array(z.object({ name: z.string().max(60), look: z.string().max(400) })).max(12),
  referenceUrl: z.string().url().optional(),
});

const FAL_MEDIA_HOST = /(^|\.)fal\.media$/;

async function toDataUri(url: string, signal: AbortSignal): Promise<string> {
  const res = await fetch(url, { signal });
  if (!res.ok) throw new Error(`Could not download image (${res.status})`);
  const type = res.headers.get("content-type") || "image/jpeg";
  const b64 = Buffer.from(await res.arrayBuffer()).toString("base64");
  return `data:${type};base64,${b64}`;
}

export async function POST(req: Request) {
  try {
    const parsed = Body.safeParse(await req.json().catch(() => null));
    if (!parsed.success) return Response.json({ error: "Invalid image request" }, { status: 400 });
    const { scene, artStyle, characters, referenceUrl } = parsed.data;
    const prompt = buildImagePrompt(scene, artStyle, characters);

    let url: string | undefined;
    const ref = referenceUrl && FAL_MEDIA_HOST.test(new URL(referenceUrl).hostname) ? referenceUrl : undefined;
    if (ref) {
      try {
        url = await falImage(
          "fal-ai/flux-pro/kontext",
          {
            prompt: `Keep the same art style and the same character designs as the reference picture. Draw this new moment: ${prompt}`,
            image_url: ref,
            aspect_ratio: "4:3",
            output_format: "jpeg",
          },
          req.signal,
        );
      } catch (e) {
        if (e instanceof Error && e.name === "AbortError") throw e;
        console.warn("Kontext failed, falling back to schnell:", e);
      }
    }
    url ??= await falImage(
      "fal-ai/flux/schnell",
      { prompt, image_size: "landscape_4_3", num_inference_steps: 4, num_images: 1, enable_safety_checker: true },
      req.signal,
    );
    return Response.json({ url, dataUri: await toDataUri(url, req.signal) });
  } catch (err) {
    return errorResponse(err);
  }
}
"}
{"file":"tests/session.test.ts","body":"import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { CLASSIC_STORIES } from "@/lib/stories";
const mocks = vi.hoisted(() => ({ post:vi.fn(), speech:vi.fn(), playBlob:vi.fn() }));
vi.mock("@/lib/audio/client", () => ({ ...mocks, Microphone: class { stop() {} } }));
import { StorySession } from "@/lib/audio/session";
const story = CLASSIC_STORIES[2];
const reply = { segments:[{speaker:"narrator",text:"Once upon a time."}],advanceBeat:false,awaitChild:true };
beforeEach(() => { vi.useFakeTimers(); vi.clearAllMocks(); mocks.post.mockResolvedValue(reply); mocks.speech.mockResolvedValue(new Blob(["audio"])); mocks.playBlob.mockResolvedValue(undefined); });
afterEach(() => vi.useRealTimers());
describe("session lifecycle", () => {
  it("ignores a turn response that arrives after interruption", async () => {
    let resolve!: (value: unknown) => void;
    mocks.post.mockImplementationOnce(() => new Promise(r => { resolve = r; }));
    const s = new StorySession(story,()=>{});
    const old = s.turn();
    await s.turn("The tortoise has roller skates!");
    resolve({ ...reply,segments:[{speaker:"narrator",text:"Old stale narration."}] });
    await old;
    expect(s.view.pages).toHaveLength(1);
    expect(s.view.state.log.some(l => l.text === "Old stale narration.")).toBe(false);
    expect(s.view.state.log[0].text).toContain("roller skates");
    s.close();
  });
  it("automatically progresses in listen mode and stops on pause", async () => {
    const s = new StorySession(story,()=>{});
    await s.turn();
    await vi.advanceTimersByTimeAsync(1200);
    expect(mocks.post).toHaveBeenCalledTimes(2);
    s.pause();
    await vi.advanceTimersByTimeAsync(3000);
    expect(mocks.post).toHaveBeenCalledTimes(2);
    s.close();
  });
  it("replays an interrupted page instead of silently skipping it", async () => {
    mocks.playBlob.mockImplementationOnce((_blob,signal: AbortSignal) => new Promise((_,reject) => { signal.addEventListener("abort",()=>reject(new DOMException("Stopped","AbortError"))); }));
    const s = new StorySession(story,()=>{});
    const pending = s.turn();
    await vi.waitFor(() => expect(mocks.playBlob).toHaveBeenCalledOnce());
    s.pause(); await pending;
    await s.turn();
    expect(mocks.post).toHaveBeenCalledOnce();
    expect(mocks.playBlob).toHaveBeenCalledTimes(2);
    s.close();
  });
  it("completes missing audio for saved interrupted pages", async () => {
    mocks.speech.mockImplementationOnce((_t,_v,signal:AbortSignal) => new Promise((_,reject) => { signal.addEventListener("abort",()=>reject(new DOMException("Stopped","AbortError"))); }));
    const s = new StorySession(story,()=>{});
    const pending = s.turn();
    await vi.waitFor(() => expect(mocks.speech).toHaveBeenCalledOnce());
    const snapshot = await s.snapshot(); await pending;
    expect(snapshot.pages[0].audio[0]).toBeInstanceOf(Blob);
    expect(mocks.speech).toHaveBeenCalledTimes(2);
    s.close();
  });
});
