{"file":"app/api/tts/route.ts","body":"import { z } from "zod";
import { deepgramKey } from "@/lib/server/deepgram";
import { errorResponse } from "@/lib/server/errors";
import { isAllowedVoice } from "@/lib/voices";

const Body = z.object({ text: z.string().trim().min(1).max(1500), voice: z.string() });

export async function POST(req: Request) {
  try {
    const parsed = Body.safeParse(await req.json().catch(() => null));
    if (!parsed.success || !isAllowedVoice(parsed.data.voice)) {
      return Response.json({ error: "Invalid text or voice" }, { status: 400 });
    }
    const { text, voice } = parsed.data;
    const res = await fetch(`https://api.deepgram.com/v1/speak?model=${voice}&encoding=mp3`, {
      method: "POST",
      signal: req.signal,
      headers: { Authorization: `Token ${deepgramKey()}`, "Content-Type": "application/json" },
      body: JSON.stringify({ text }),
    });
    if (!res.ok || !res.body) {
      throw new Error(`Deepgram TTS error ${res.status}: ${(await res.text()).slice(0, 300)}`);
    }
    return new Response(res.body, { headers: { "Content-Type": "audio/mpeg", "Cache-Control": "no-store" } });
  } catch (err) {
    return errorResponse(err);
  }
}
"}
{"file":"lib/engine/schema.ts","body":"import { z } from "zod";

const shortText = (max: number) => z.string().trim().min(1).max(max);

export const TurnSchema = z.object({
  segments: z
    .array(z.object({ speaker: shortText(60), text: shortText(600) }))
    .min(1)
    .max(6),
  stateChanges: z
    .object({
      addCharacters: z
        .array(
          z.object({
            name: shortText(60),
            personality: shortText(300),
            look: shortText(300),
            voice: z.string().optional(),
          }),
        )
        .max(3)
        .optional(),
      addObjects: z.array(shortText(120)).max(5).optional(),
      plotNotes: z.array(shortText(300)).max(5).optional(),
    })
    .prefault({}),
  advanceBeat: z.boolean().default(false),
  imagePrompt: z.string().trim().max(800).nullish(),
  awaitChild: z.boolean().default(false),
  isEnding: z.boolean().default(false),
});

export type Turn = z.infer<typeof TurnSchema>;

const VoiceField = z.string().optional();

export const CreateReplySchema = z.object({
  say: shortText(600),
  done: z.boolean().default(false),
  story: z
    .object({
      title: shortText(80),
      emoji: z.string().max(8).optional(),
      blurb: shortText(300),
      setting: shortText(400),
      characters: z
        .array(
          z.object({
            name: shortText(60),
            personality: shortText(300),
            look: shortText(300),
            voice: VoiceField,
          }),
        )
        .min(1)
        .max(5),
      beats: z.array(z.object({ title: shortText(80), goal: shortText(300) })).min(3).max(7),
    })
    .nullish(),
});

export type CreateReply = z.infer<typeof CreateReplySchema>;

export function extractJson(raw: string): unknown {
  const fenced = raw.match(/```(?:json)?\s*([\s\S]*?)```/i);
  const body = fenced ? fenced[1] : raw;
  const start = body.indexOf("{");
  const end = body.lastIndexOf("}");
  if (start === -1 || end <= start) throw new Error("No JSON object in model output");
  return JSON.parse(body.slice(start, end + 1));
}
"}
