{"file":"components/StoryPlayer.tsx","body":""use client";
import { useEffect, useRef, useState } from "react";
import Link from "next/link";
import type { StoryDef } from "@/lib/types";
import { StorySession, type SessionView } from "@/lib/audio/session";
import { saveAdventure } from "@/lib/db";
import { initialState } from "@/lib/engine/reducer";
import Scene from "./Scene";
import BlobImage from "./BlobImage";
export default function StoryPlayer({ story }: { story: StoryDef }) {
  const session = useRef<StorySession | null>(null);
  const [view, setView] = useState<SessionView>(() => ({ state: initialState(story, "listen"), pages: [], status: "Ready when you are", error: "", listening: false, imageBusy: false }));
  const latest = useRef(view);
  const [text, setText] = useState("");
  const [notice, setNotice] = useState("");
  const [saving, setSaving] = useState(false);
  useEffect(() => { const s = new StorySession(story, next => { latest.current = next; setView(next); }, latest.current); session.current = s; return () => { s.close(); session.current = null; }; }, [story]);
  const page = view?.pages.at(-1);
  async function save() {
    if (!session.current) return;
    setSaving(true);
    try { const snapshot = await session.current.snapshot(); await saveAdventure({ ...snapshot, title: `${story.title} · My version` }); setNotice("Saved! Your original story is still on the shelf."); }
    catch { setNotice("Couldn’t save. Your browser may be out of storage or have storage disabled."); }
    finally { setSaving(false); }
  }
  return <main className="reader"><Link className="back-link" href="/">← Back to the story shelf</Link><div className="reader-heading"><div><p className="eyebrow">YOUR NEXT CHAPTER</p><h1>{story.title}</h1></div><button className="button secondary" disabled={!page || saving} onClick={save}>{saving ? "Saving the magic…" : "♡ Save this version"}</button></div><div className="reader-grid"><section className="picture-panel">{page?.image ? <BlobImage blob={page.image} alt={page.scene || story.setting}/> : <Scene kind={story.id}/>}<span className="picture-caption">{view?.imageBusy ? "✧ The page is changing…" : `Chapter ${(view?.state.beatIndex ?? 0) + 1} · ${story.beats[view?.state.beatIndex ?? 0]?.title}`}</span></section><section className="reading-panel"><div className="mode-switch"><button aria-pressed={view?.state.mode === "listen"} onClick={() => void session.current?.mode("listen")}>♫ Listen</button><button aria-pressed={view?.state.mode === "play"} onClick={() => void session.current?.mode("play")}>◉ Play & talk</button></div><p className={`status ${view?.listening ? "listening" : ""}`} role="status">{view?.listening && <span className="live-dot"/>}{view?.status ?? "Opening your story…"}</p><div className="narration" aria-live="polite">{page ? page.segments.map((s,i) => <div key={i}><span className="speaker">{s.speakerName}</span><p>{s.text}</p></div>) : <><h2>Once upon a time…</h2><p>{story.blurb}</p><p className="muted small">Choose Listen to sit back, or Play & talk to jump into the adventure. Headphones help the story hear just your voice.</p></>}</div><div className="playback-controls"><button className="button primary" onClick={() => void session.current?.turn()} disabled={view?.state.ended}>{page ? "Continue →" : "Begin the story →"}</button><button className="button secondary" onClick={() => session.current?.pause()}>Pause</button></div>{view?.state.ended && <Link href="/" className="back-link">Find another adventure →</Link>}</section></div><div className="interaction-bar"><span className="mic-symbol">✧</span><form onSubmit={e => { e.preventDefault(); if (text.trim()) { void session.current?.turn(text.trim()); setText(""); } }}><label htmlFor="story-idea">{view?.listening ? "Your microphone is on. Jump in anytime!" : "A little idea can change everything."}</label><div className="input-row"><input id="story-idea" value={text} maxLength={600} onChange={e => setText(e.target.value)} placeholder='Try “The tortoise has roller skates!”'/><button type="submit" aria-label="Add your idea" disabled={!text.trim()}>↑</button></div></form><p>Talk to a character.<br/>Dream up a twist.<br/>Make it yours.</p></div>{view?.error && <p className="error" role="alert">{view.error}</p>}{notice && <p className="notice" role="status">{notice} <Link href="/adventures">My adventures →</Link></p>}<details className="transcript"><summary>Our adventure so far</summary>{view?.state.log.map((e,i) => <p key={i}><strong>{e.kind === "child" ? "You" : e.speaker}:</strong> {e.text}</p>)}</details></main>;
}
"}
{"file":"lib/engine/streamSegments.ts","body":"import type { Turn } from "@/lib/engine/schema";

export interface StreamedSegment {
  speaker: string;
  text: string;
}

export type TurnEvent =
  | ({ type: "segment" } & StreamedSegment)
  | { type: "turn"; turn: Turn }
  | { type: "error"; error: string };

const SEGMENT = /\{\s*"speaker"\s*:\s*("(?:[^"\\]|\\.)*")\s*,\s*"text"\s*:\s*("(?:[^"\\]|\\.)*")\s*\}/g;

/** Segments whose JSON objects are fully written in a partial model reply. */
export function completedSegments(partial: string): StreamedSegment[] {
  const start = partial.indexOf('"segments"');
  if (start === -1) return [];
  let region = partial.slice(start);
  const end = region.indexOf('"stateChanges"');
  if (end !== -1) region = region.slice(0, end);
  const out: StreamedSegment[] = [];
  for (const m of region.matchAll(SEGMENT)) {
    try {
      const speaker = String(JSON.parse(m[1])).trim().slice(0, 60);
      const text = String(JSON.parse(m[2])).trim().slice(0, 600);
      if (speaker && text) out.push({ speaker, text });
    } catch {
      // A malformed escape sequence; the final validated turn still covers it.
    }
    if (out.length === 6) break;
  }
  return out;
}
"}
{"file":"lib/audio/session.ts","body":"import type { Mode, StoryDef, StoryState } from "@/lib/types";
import { initialState, applyTurn, addChildUtterance } from "@/lib/engine/reducer";
import { TurnSchema } from "@/lib/engine/schema";
import { Microphone, playBlob, post, speech } from "./client";
import type { AdventurePage } from "@/lib/db";
import { isLikelyEcho } from "@/lib/engine/echo";

export interface SessionView {
  state: StoryState;
  pages: AdventurePage[];
  status: string;
  error: string;
  listening: boolean;
  imageBusy: boolean;
}
export class StorySession {
  view: SessionView;
  private controller?: AbortController;
  private mic?: Microphone;
  private generation = 0;
  private timer?: ReturnType<typeof setTimeout>;
  private referenceUrl?: string;
  private imageJobs = new Set<Promise<void>>();
  private imageControllers = new Set<AbortController>();
  private closed = false;
  private paused = true;
  private pendingPage?: AdventurePage;
  private recentlySpoken = "";
  private spokenAt = 0;
  private snapshotting = false;
  constructor(story: StoryDef, private update: (view: SessionView) => void, restored?: SessionView) {
    this.view = restored ? { ...restored, listening: false, imageBusy: false } : { state: initialState(story, "listen"), pages: [], status: "Ready when you are", error: "", listening: false, imageBusy: false };
  }
  private emit() { if (!this.closed) this.update({ ...this.view, pages: [...this.view.pages] }); }
  stopTurn() { clearTimeout(this.timer); this.generation++; this.controller?.abort(); }
  pause() { this.paused = true; this.stopTurn(); this.view.status = "Paused"; this.emit(); }
  async mode(mode: Mode) {
    this.mic?.stop(); this.mic = undefined;
    this.view.state = { ...this.view.state, mode }; this.view.listening = false;
    this.emit();
    if (mode === "play") {
      const mic = this.mic = new Microphone();
      try {
        await mic.start(
          text => { if (!this.closed && this.mic === mic && !this.echo(text)) { this.stopTurn(); this.view.status = "I’m listening…"; this.emit(); } },
          text => { if (this.mic === mic && !this.echo(text)) void this.turn(text); },
          error => { this.view.error = error; this.view.listening = false; this.emit(); },
        );
        if (this.mic === mic && !this.closed) this.view.listening = true;
      } catch (e) { this.view.error = String((e as Error).message); }
      this.emit();
    }
  }
  private echo(text: string) { return Date.now() - this.spokenAt < 15000 && isLikelyEcho(text, this.recentlySpoken); }
  private async narrate(page: AdventurePage, controller: AbortController, current: () => boolean) {
    const loads = page.segments.map((s,i) => page.audio[i] ? Promise.resolve(page.audio[i]) : speech(s.text, s.voice, controller.signal));
    loads.forEach(p => { void p.catch(() => {}); });
    for (let i = 0; i < loads.length; i++) {
      const blob = await loads[i];
      if (!current()) return;
      page.audio[i] = blob;
      this.recentlySpoken = page.segments[i].text; this.spokenAt = Date.now() + page.segments[i].text.length * 90;
      this.view.status = `${page.segments[i].speakerName} is speaking`; this.emit();
      await playBlob(blob, controller.signal);
      this.spokenAt = Date.now();
    }
  }
  async turn(text?: string) {
    if (this.closed || this.snapshotting || (this.view.state.ended && !text && !this.pendingPage)) return;
    this.stopTurn(); this.paused = false;
    const generation = this.generation;
    const controller = this.controller = new AbortController();
    const current = () => !this.closed && generation === this.generation;
    if (text) this.view.state = { ...addChildUtterance(this.view.state, text), ended: false };
    this.view.error = ""; this.view.status = "Turning your ideas into a story…"; this.emit();
    try {
      if (!text && this.pendingPage) {
        const page = this.pendingPage;
        await this.narrate(page, controller, current);
        if (!current()) return;
        this.pendingPage = undefined;
        this.view.status = this.view.state.ended ? "The End. What a lovely adventure!" : "Ready for the next page"; this.emit();
        if (!this.view.state.ended) this.timer = setTimeout(() => { if (!this.paused) void this.turn(); }, 1200);
        return;
      }
      this.pendingPage = undefined;
      const raw = await post("/api/turn", { state: this.view.state }, controller.signal);
      if (!current()) return;
      const turn = TurnSchema.parse(raw);
      const applied = applyTurn(this.view.state, turn);
      this.view.state = applied.state;
      const page: AdventurePage = { segments: applied.spoken, audio: [], scene: turn.imagePrompt ?? undefined, image: this.view.pages.at(-1)?.image };
      this.pendingPage = page;
      this.view.pages.push(page); this.emit();
      if (turn.imagePrompt) this.illustrate(page, turn.imagePrompt);
      await this.narrate(page, controller, current);
      if (!current()) return;
      this.pendingPage = undefined;
      this.view.status = this.view.state.ended ? "The End. What a lovely adventure!" : turn.awaitChild ? "What happens next? Tell me!" : "A little more magic…"; this.emit();
      if (!this.view.state.ended && !(turn.awaitChild && this.view.state.mode === "play")) {
        this.timer = setTimeout(() => { if (!this.paused) void this.turn(); }, 1200);
      }
    } catch (e) {
      if (current() && (e as Error).name !== "AbortError") { this.view.error = (e as Error).message; this.view.status = "Let’s try that again"; this.emit(); }
    }
  }
  private illustrate(page: AdventurePage, scene: string) {
    const controller = new AbortController();
    this.imageControllers.add(controller);
    this.view.imageBusy = true; this.emit();
    const job = (async () => {
      try {
        const data = await post<{ url: string; dataUri: string }>("/api/image", { scene, artStyle: this.view.state.story.artStyle, characters: this.view.state.characters, referenceUrl: this.referenceUrl }, controller.signal);
        if (this.closed) return;
        page.image = await (await fetch(data.dataUri)).blob();
        if (this.view.pages.at(-1) === page) this.referenceUrl = data.url;
      } catch (e) { if (!this.closed && (e as Error).name !== "AbortError") this.view.error = `Illustration: ${(e as Error).message}`; }
    })();
    this.imageJobs.add(job);
    void job.finally(() => { this.imageJobs.delete(job); this.imageControllers.delete(controller); this.view.imageBusy = this.imageJobs.size > 0; this.emit(); });
  }
  async snapshot() {
    this.snapshotting = true;
    this.pause();
    this.mic?.stop(); this.mic = undefined; this.view.listening = false; this.emit();
    try {
      await Promise.all([...this.imageJobs]);
      // Interrupted pages still need complete audio for offline replay.
      for (const page of this.view.pages) {
        for (let i = 0; i < page.segments.length; i++) {
          if (!page.audio[i]) {
            const s = page.segments[i];
            page.audio[i] = await speech(s.text, s.voice, AbortSignal.timeout(30000));
          }
        }
      }
      return structuredClone({ story: this.view.state.story, state: this.view.state, pages: this.view.pages });
    } finally { this.snapshotting = false; }
  }
  close() {
    this.closed = true; this.stopTurn(); this.mic?.stop();
    this.imageControllers.forEach(c => c.abort());
  }
}
"}
{"file":"lib/server/fal.ts","body":"import "server-only";

const FAL_BASE = "https://fal.run";
const CHAT_URL = `${FAL_BASE}/openrouter/router/openai/v1/chat/completions`;

export class ConfigError extends Error {}

function falKey(): string {
  const key = process.env.FAL_KEY;
  if (!key) throw new ConfigError("FAL_KEY is not set. Add it to .env.local.");
  return key;
}

export const LLM_MODEL = process.env.FAL_LLM_MODEL || "google/gemini-2.5-flash";

function chatRequest(system: string, user: string, signal: AbortSignal | undefined, stream: boolean, extra?: string) {
  const messages = [
    { role: "system", content: system },
    { role: "user", content: user },
  ];
  if (extra) messages.push({ role: "user", content: extra });
  return fetch(CHAT_URL, {
    method: "POST",
    signal,
    headers: { Authorization: `Key ${falKey()}`, "Content-Type": "application/json" },
    body: JSON.stringify({
      model: LLM_MODEL,
      messages,
      temperature: 0.8,
      max_tokens: 1200,
      response_format: { type: "json_object" },
      // Reasoning adds roughly half a second before the first word and does not improve short story turns.
      reasoning: { enabled: false },
      stream,
    }),
  });
}

export async function chatJSON(system: string, user: string, signal?: AbortSignal, extra?: string): Promise<string> {
  const res = await chatRequest(system, user, signal, false, extra);
  if (!res.ok) throw new Error(`fal LLM error ${res.status}: ${(await res.text()).slice(0, 300)}`);
  const data = (await res.json()) as { choices?: { message?: { content?: string } }[] };
  const content = data.choices?.[0]?.message?.content;
  if (!content) throw new Error("fal LLM returned no content");
  return content;
}

/** Resolves once the model has accepted the request, then yields content deltas as they arrive. */
export async function chatStream(system: string, user: string, signal?: AbortSignal): Promise<AsyncGenerator<string>> {
  const res = await chatRequest(system, user, signal, true);
  if (!res.ok || !res.body) throw new Error(`fal LLM error ${res.status}: ${(await res.text()).slice(0, 300)}`);
  const reader = res.body.getReader();
  return (async function* () {
    const decoder = new TextDecoder();
    let buffer = "";
    for (;;) {
      const { done, value } = await reader.read();
      if (done) return;
      buffer += decoder.decode(value, { stream: true });
      let newline: number;
      while ((newline = buffer.indexOf("\n")) !== -1) {
        const line = buffer.slice(0, newline).trim();
        buffer = buffer.slice(newline + 1);
        if (!line.startsWith("data:")) continue;
        const data = line.slice(5).trim();
        if (data === "[DONE]") return;
        let chunk: { error?: { message?: string }; choices?: { delta?: { content?: string } }[] };
        try {
          chunk = JSON.parse(data);
        } catch {
          continue;
        }
        if (chunk.error) throw new Error(`fal LLM error: ${chunk.error.message ?? "stream failed"}`);
        const content = chunk.choices?.[0]?.delta?.content;
        if (content) yield content;
      }
    }
  })();
}

interface FalImageResult {
  images?: { url: string; content_type?: string }[];
}

export async function falImage(endpoint: string, input: Record<string, unknown>, signal?: AbortSignal): Promise<string> {
  const res = await fetch(`${FAL_BASE}/${endpoint}`, {
    method: "POST",
    signal,
    headers: { Authorization: `Key ${falKey()}`, "Content-Type": "application/json" },
    body: JSON.stringify(input),
  });
  if (!res.ok) throw new Error(`fal ${endpoint} error ${res.status}: ${(await res.text()).slice(0, 300)}`);
  const data = (await res.json()) as FalImageResult;
  const url = data.images?.[0]?.url;
  if (!url) throw new Error(`fal ${endpoint} returned no image`);
  return url;
}
"}
